mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM app_chat_message
    WHERE tenant_id = #{tenantId}
      AND session_id = #{sessionId}
      AND role = 'user'
      AND client_message_id = #{clientMessageId}
)

mapper.update:
UPDATE app_chat_session
SET last_message_at = #{updatedAt},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND id = #{sessionId}
  AND deleted_at IS NULL

mapper.select:
SELECT tenant_id, chat_message_id, knowledge_base_id, document_id, chunk_id, score, citation_text, created_at FROM kb_citation_record WHERE tenant_id = #{tenantId} AND chat_message_id IN
#{messageId}
ORDER BY chat_message_id ASC, created_at ASC
